/**
 * Nightshift for Hermes Desktop: a live pane for watched training runs and a status-bar chip.
 * Disk plugins load uncompiled: no JSX; imports limited to @hermes/plugin-sdk, react, react/jsx-runtime.
 * Data comes from the plugin's backend routes (dashboard/plugin_api.py) through ctx.rest.
 */

import { STATUSBAR_AREAS, Tip, host } from '@hermes/plugin-sdk'
import { jsx } from 'react/jsx-runtime'
import { useEffect, useState } from 'react'

function h(type, props, ...children) {
  const { key, ...rest } = props || {}
  const kids = children.filter(c => c !== null && c !== undefined && c !== false)
  const all = kids.length === 0 ? undefined : kids.length === 1 ? kids[0] : kids
  return jsx(type, all === undefined ? rest : { ...rest, children: all }, key)
}

const THEME = {
  text: 'var(--ui-text-primary)',
  muted: 'var(--ui-text-tertiary)',
  border: 'var(--ui-stroke-secondary)',
  surface: 'var(--ui-bg-card)',
  chartBg: 'var(--ui-bg-tertiary)',
  accent: 'var(--ui-accent)',
  onAccent: 'var(--ui-bg-primary)',
  good: 'var(--ui-green)',
  warn: 'var(--ui-yellow)',
  bad: 'var(--ui-red)',
  val: 'var(--ui-green)',
  series1: 'var(--ui-accent)',
  series2: 'var(--ui-cyan)',
  series3: 'var(--ui-blue)',
  series4: 'var(--ui-purple)'
}

/* Nightshift UI core: shared by the Desktop pane and the web-dashboard tab.
 *
 * Host-agnostic: everything comes in through `env`:
 *   h(type, props, ...children)   element factory (React.createElement-compatible)
 *   useState, useEffect           React hooks
 *   api.get(path) / api.post(path) the plugin's backend routes (/api/plugins/nightshift/...)
 *   theme                          CSS colour expressions for the host's theme variables
 *   onNewAlerts(alerts)            optional: called with critical incidents seen for the first time
 *
 * No JSX (Desktop loads plugins uncompiled), no DOM access, no globals. Built into both outputs by
 * scripts/build_ui.py.
 */

function makeNightshiftUI(env) {
  const { h, useState, useEffect, api, theme } = env
  const POLL_MS = 2000

  // ---- data ------------------------------------------------------------------------------------------------
  const listeners = new Set()
  let latest = null
  let lastError = null
  let timer = null
  const seenAlerts = new Set()
  let primed = false

  async function refresh() {
    try {
      latest = await api.get('/status')
      lastError = null
      const fresh = (latest.alerts || []).filter(a => !seenAlerts.has(a.id))
      fresh.forEach(a => seenAlerts.add(a.id))
      if (primed && fresh.length && env.onNewAlerts) env.onNewAlerts(fresh, latest)
      primed = true
    } catch (err) {
      lastError = String((err && err.message) || err)
    }
    listeners.forEach(fn => fn())
  }

  function subscribe(fn) {
    listeners.add(fn)
    if (!timer) {
      refresh()
      timer = setInterval(refresh, POLL_MS)
    }
    return () => {
      listeners.delete(fn)
      if (!listeners.size && timer) {
        clearInterval(timer)
        timer = null
      }
    }
  }

  function useStatus() {
    const [, bump] = useState(0)
    useEffect(() => subscribe(() => bump(n => n + 1)), [])
    return { status: latest, error: lastError }
  }

  async function act(path) {
    try {
      await api.post(path)
    } finally {
      refresh()
    }
  }

  // ---- formatting ------------------------------------------------------------------------------------------
  const HEALTH = {
    healthy: ['●', theme.good, 'healthy'],
    warning: ['●', theme.warn, 'warning'],
    critical: ['●', theme.bad, 'critical'],
    finished: ['✓', theme.good, 'finished'],
    stopped: ['○', theme.muted, 'stopped'],
    failed: ['✕', theme.bad, 'failed']
  }
  const ICON = {
    rollback_restart: '↺',
    oom_restart: '⇣',
    stop: '■',
    notify: '•'
  }

  function fmtNum(v) {
    if (v === null || v === undefined) return '—'
    if (typeof v === 'string') return v
    if (Math.abs(v) >= 1000 || (Math.abs(v) > 0 && Math.abs(v) < 0.001)) return v.toExponential(2)
    return v.toPrecision(4)
  }

  function fmtTime(t) {
    const d = new Date(t * 1000)
    return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
  }

  function fmtDur(s) {
    if (s === null || s === undefined) return ''
    if (s < 90) return `${Math.round(s)}s`
    if (s < 5400) return `${Math.round(s / 60)}m`
    return `${(s / 3600).toFixed(1)}h`
  }

  // ---- pieces ----------------------------------------------------------------------------------------------
  const S = {
    pane: { display: 'flex', flexDirection: 'column', gap: 10, padding: 12, fontSize: 12.5, color: theme.text,
      height: '100%', overflowY: 'auto', boxSizing: 'border-box' },
    card: { border: `1px solid ${theme.border}`, borderRadius: 10, padding: 10, background: theme.surface,
      display: 'flex', flexDirection: 'column', gap: 8 },
    row: { display: 'flex', alignItems: 'center', gap: 8 },
    muted: { color: theme.muted },
    mono: { fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: 11.5, wordBreak: 'break-all' },
    btn: { border: `1px solid ${theme.border}`, background: 'transparent', color: theme.text, borderRadius: 6,
      padding: '3px 10px', cursor: 'pointer', fontSize: 12 },
    primary: { border: `1px solid ${theme.accent}`, background: theme.accent, color: theme.onAccent,
      borderRadius: 6, padding: '3px 12px', cursor: 'pointer', fontSize: 12, fontWeight: 600 }
  }

  function Button({ label, onClick, primary, danger, title }) {
    const style = primary ? S.primary : danger ? { ...S.btn, color: theme.bad, borderColor: theme.bad } : S.btn
    return h('button', { type: 'button', style, onClick, title }, label)
  }

  function ConfirmButton({ label, confirmLabel, onConfirm }) {
    const [armed, setArmed] = useState(false)
    useEffect(() => {
      if (!armed) return undefined
      const id = setTimeout(() => setArmed(false), 4000)
      return () => clearTimeout(id)
    }, [armed])
    return armed
      ? h(Button, { label: confirmLabel, danger: true, onClick: () => { setArmed(false); onConfirm() } })
      : h(Button, { label, onClick: () => setArmed(true) })
  }

  function Chart({ run }) {
    const W = 300
    const H = 96
    const PAD = 4
    const names = Object.keys(run.series || {})
    const train = names.find(n => !/val|eval|test|valid/.test(n))
    const val = names.find(n => /val|eval|test|valid/.test(n))
    const tp = (train && run.series[train]) || []
    const vp = (val && run.series[val]) || []
    const all = tp.concat(vp)
    if (all.length < 2) {
      return h('div', { style: { ...S.muted, height: H, display: 'flex', alignItems: 'center',
        justifyContent: 'center' } }, 'waiting for metrics…')
    }
    const finite = all.filter(p => typeof p.value === 'number' && isFinite(p.value))
    // x is the training step: after a rollback the new attempt restarts at the checkpoint's step and is drawn
    // over the branch that diverged, so the chart shows the fork.
    const markers = (run.markers || []).filter(m => typeof m.step === 'number')
    const recoveries = (run.recoveries || []).filter(r => typeof r.step === 'number')
    const steps = all.map(p => p.step).concat(markers.map(m => m.step), recoveries.map(r => r.step))
    const x0 = Math.min(...steps)
    const x1 = Math.max(...steps, x0 + 1)
    const lastAttempt = Math.max(0, ...tp.map(p => p.attempt || 0))
    const vals = finite.map(p => p.value)
    // fit the y-axis to the bulk of the curve: a blow-up to 60x the loss runs off the top instead of
    // flattening everything else into the bottom pixels
    const sorted = vals.slice().sort((a, b) => a - b)
    const q = f => sorted[Math.min(sorted.length - 1, Math.floor(f * (sorted.length - 1)))]
    const hiCap = sorted.length > 10 && q(1) > 3 * q(0.9) ? q(0.9) * 1.6 : q(1)
    const shown = vals.filter(v => v <= hiCap)
    const useLog = shown.length && Math.min(...shown) > 0 && Math.max(...shown) / Math.min(...shown) > 50
    const tf = v => (useLog ? Math.log10(v) : v)
    let y0 = shown.length ? Math.min(...shown.map(tf)) : 0
    let y1 = shown.length ? Math.max(...shown.map(tf)) : 1
    if (y1 === y0) y1 = y0 + 1
    const pad = (y1 - y0) * 0.08
    y0 -= pad
    y1 += pad
    const sx = s => PAD + ((s - x0) / (x1 - x0)) * (W - 2 * PAD)
    const sy = v => Math.max(-2, H - PAD - ((tf(v) - y0) / (y1 - y0)) * (H - 2 * PAD))

    function paths(points, colorFor) {
      const out = []
      let seg = []
      let attempt = null
      const flush = () => {
        if (seg.length > 1) {
          out.push(h('polyline', { key: `p${out.length}`, points: seg.join(' '), fill: 'none',
            stroke: colorFor(attempt), strokeWidth: 1.6, vectorEffect: 'non-scaling-stroke',
            strokeLinejoin: 'round', strokeOpacity: (attempt || 0) < lastAttempt ? 0.4 : 1 }))
        }
        seg = []
      }
      points.forEach(p => {
        const ok = typeof p.value === 'number' && isFinite(p.value) && (!useLog || p.value > 0)
        if (!ok || p.attempt !== attempt) flush()
        attempt = p.attempt
        if (ok) seg.push(`${sx(p.step).toFixed(1)},${sy(p.value).toFixed(1)}`)
      })
      flush()
      return out
    }

    const shades = [theme.series1, theme.series2, theme.series3, theme.series4]
    const nanTicks = tp.filter(p => typeof p.value !== 'number' || !isFinite(p.value))
    return h('svg', { viewBox: `0 0 ${W} ${H}`, preserveAspectRatio: 'none',
      style: { width: '100%', height: H, display: 'block', overflow: 'hidden', borderRadius: 6 } },
      h('rect', { x: 0, y: 0, width: W, height: H, fill: theme.chartBg, rx: 6 }),
      ...recoveries.map((r, i) => h('line', { key: `r${i}`, x1: sx(r.step), x2: sx(r.step), y1: 0, y2: H,
        stroke: theme.warn, strokeWidth: 1.2, strokeDasharray: '3 3', vectorEffect: 'non-scaling-stroke' },
        h('title', null, `${fmtTime(r.at)} ${r.message}`))),
      ...paths(vp, () => theme.val),
      ...paths(tp, a => shades[(a || 0) % shades.length]),
      ...markers.map((m, i) => h('line', { key: `m${i}`, x1: sx(m.step), x2: sx(m.step), y1: 0, y2: H,
        stroke: m.severity === 'critical' ? theme.bad : theme.warn, strokeWidth: 1.4,
        vectorEffect: 'non-scaling-stroke' }, h('title', null, `${fmtTime(m.at)} ${m.message}`))),
      ...nanTicks.slice(0, 40).map((p, i) => h('rect', { key: `n${i}`, x: sx(p.step) - 1.5, y: 1, width: 3,
        height: 5, fill: theme.bad }))
    )
  }

  function ChartCaption({ run }) {
    const names = Object.keys(run.series || {})
    const tp = (names.length && run.series[names.find(n => !/val|eval|test|valid/.test(n)) || names[0]]) || []
    if (tp.length < 2) return null
    const lo = Math.min(...tp.map(p => p.step))
    const hi = Math.max(...tp.map(p => p.step))
    const key = (color, label, dashed) => h('span', { style: { display: 'inline-flex', alignItems: 'center', gap: 4 } },
      h('span', { style: { width: 12, borderTop: `2px ${dashed ? 'dashed' : 'solid'} ${color}` } }), label)
    return h('div', { style: { ...S.row, ...S.muted, fontSize: 10.5, flexWrap: 'wrap', rowGap: 2 } },
      h('span', { style: { fontVariantNumeric: 'tabular-nums' } }, `step ${lo}`),
      key(theme.series1, 'train'),
      names.some(n => /val|eval|test|valid/.test(n)) ? key(theme.val, 'val') : null,
      (run.markers || []).some(m => typeof m.step === 'number') ? key(theme.bad, 'incident') : null,
      (run.recoveries || []).some(r => typeof r.step === 'number') ? key(theme.warn, 'restored from', true) : null,
      h('span', { style: { marginLeft: 'auto', fontVariantNumeric: 'tabular-nums' } }, `step ${hi}`))
  }

  function Pending({ run }) {
    const card = run.card || {}
    return h('div', { style: { ...S.card, borderColor: theme.accent } },
      h('div', { style: S.row },
        h('strong', null, `Approve run "${run.name}"?`),
        h('span', { style: { ...S.muted, marginLeft: 'auto' } }, run.id)),
      h('div', { style: S.mono }, card.command || ''),
      h('div', { style: S.muted }, card.cwd || ''),
      h('ul', { style: { margin: 0, paddingLeft: 16, display: 'flex', flexDirection: 'column', gap: 2 } },
        ...(card.playbook || []).map((ln, i) => h('li', { key: i }, ln))),
      h('div', { style: S.row },
        h(Button, { label: 'Approve & launch', primary: true, onClick: () => act(`/approve/${run.id}`) }),
        h(Button, { label: 'Decline', onClick: () => act(`/deny/${run.id}`) })))
  }

  function Run({ run }) {
    const [glyph, color, label] = HEALTH[run.health] || HEALTH.healthy
    const active = ['running', 'recovering', 'starting', 'approved'].includes(run.status)
    const stat = (k, v) => h('div', { style: { display: 'flex', flexDirection: 'column', minWidth: 0 } },
      h('span', { style: { ...S.muted, fontSize: 10.5, textTransform: 'uppercase', letterSpacing: 0.4 } }, k),
      h('span', { style: { fontVariantNumeric: 'tabular-nums' } }, v))
    return h('div', { style: S.card },
      h('div', { style: S.row },
        h('span', { style: { color, fontSize: 14 } }, glyph),
        h('strong', { style: { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, run.name),
        h('span', { style: S.muted }, run.mode === 'watch' ? 'watching' : run.status),
        h('span', { style: { ...S.muted, marginLeft: 'auto' } }, run.id)),
      h('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 6 } },
        stat('step', run.step === null || run.step === undefined ? '—' : run.step),
        stat('loss', fmtNum(run.train_loss && run.train_loss.value)),
        stat('val', fmtNum(run.val_loss && run.val_loss.value)),
        stat('fixes', `${run.interventions}${run.attempt ? ` · try ${run.attempt + 1}` : ''}`)),
      h(Chart, { run }),
      h(ChartCaption, { run }),
      run.diagnosis ? h('div', { style: { ...S.muted, fontStyle: 'italic' } }, `Why: ${run.diagnosis}`) : null,
      (run.timeline || []).length
        ? h('div', { style: { display: 'flex', flexDirection: 'column', gap: 3 } },
          ...run.timeline.map((a, i) => h('div', { key: i, style: { ...S.row, alignItems: 'flex-start' } },
            h('span', { style: { ...S.muted, fontVariantNumeric: 'tabular-nums' } }, fmtTime(a.at)),
            h('span', { style: { color: a.kind === 'stop' || !a.ok ? theme.bad : a.kind === 'notify' ? theme.muted
              : theme.good } }, ICON[a.kind] || '•'),
            h('span', null, a.message))))
        : null,
      h('div', { style: S.row },
        h('span', { style: { ...S.muted, fontSize: 11 } }, `${label}${run.uptime_s ? ` · ${fmtDur(run.uptime_s)}` : ''}`),
        h('span', { style: { marginLeft: 'auto' } },
          active && run.mode === 'launch'
            ? h(ConfirmButton, { label: 'Stop', confirmLabel: 'Confirm stop', onConfirm: () => act(`/stop/${run.id}`) })
            : null)))
  }

  function Pane() {
    const { status, error } = useStatus()
    const runs = (status && status.runs) || []
    const pending = runs.filter(r => r.status === 'pending')
    const others = runs.filter(r => r.status !== 'pending')
    const unacked = (status && status.unacknowledged_incidents) || 0
    return h('div', { style: S.pane },
      h('div', { style: S.row },
        h('span', { style: { fontSize: 16 } }, '☾'),
        h('strong', { style: { fontSize: 14 } }, 'Nightshift'),
        h('span', { style: S.muted }, runs.length ? `${others.filter(r => ['running', 'recovering'].includes(r.status)).length} running` : ''),
        unacked ? h('span', { style: { marginLeft: 'auto' } },
          h(Button, { label: `Mark ${unacked} seen`, onClick: () => act('/ack') })) : null),
      error ? h('div', { style: { ...S.card, color: theme.muted } }, `Can't reach Nightshift: ${error}`) : null,
      ...pending.map(r => h(Pending, { key: r.id, run: r })),
      ...others.map(r => h(Run, { key: r.id, run: r })),
      !error && status && !runs.length
        ? h('div', { style: { ...S.card, ...S.muted } },
          'No runs yet. Ask Hermes something like: "train model.py with lr 3e-4 and watch it overnight".')
        : null)
  }

  function Chip() {
    const { status, error } = useStatus()
    const runs = (status && status.runs) || []
    const running = runs.filter(r => ['running', 'recovering'].includes(r.status))
    const critical = runs.some(r => r.health === 'critical')
    const pending = runs.some(r => r.status === 'pending')
    const color = error ? theme.muted : critical ? theme.bad : pending ? theme.warn : theme.accent
    const label = error ? 'Nightshift offline'
      : pending ? 'A run is waiting for your approval'
        : running.length ? running.map(r => `${r.name}: ${r.health}`).join(' · ') : 'Nightshift: no runs'
    return { color, text: `☾ ${running.length}${pending ? ' ·!' : ''}`, label }
  }

  return { Pane, Chip, refresh, subscribe }
}

export default {
  id: 'nightshift',
  name: 'Nightshift',
  register(ctx) {
    const ui = makeNightshiftUI({
      h,
      useState,
      useEffect,
      theme: THEME,
      api: {
        get: path => ctx.rest(path),
        post: path => ctx.rest(path, { method: 'POST' })
      },
      onNewAlerts: alerts => {
        for (const a of alerts.slice(0, 3)) {
          const body = a.message
          ctx.os.notify({ title: `Nightshift: ${a.kind.replace('_', ' ')}`, body })
          host.notify({ kind: 'error', message: `Nightshift: ${body}` })
        }
      }
    })

    ctx.register({
      id: 'pane',
      area: 'panes',
      title: 'Nightshift',
      data: { placement: 'right', width: '360px' },
      render: () => jsx(ui.Pane, {})
    })

    function ChipView() {
      const chip = ui.Chip()
      return jsx(Tip, {
        label: chip.label,
        children: jsx('span', {
          className: 'inline-flex h-full items-center gap-1 px-1.5 text-[0.6875rem]',
          style: { color: chip.color, fontVariantNumeric: 'tabular-nums' },
          children: chip.text
        })
      })
    }

    ctx.register({ id: 'chip', area: STATUSBAR_AREAS.right, order: 125, render: () => jsx(ChipView, {}) })
  }
}
